			records, err := scanHistoryFileReader(context.Background(), strings.NewReader(data), rel, ".jsonl")
			wantRecords := 1
			wantSkipped := 1
			wantResponse := ""
			if extra == 0 {
				wantRecords = 2
				wantSkipped = 0
				wantResponse = "Decision: boundary response\nDecision: final response"
			}
			decisions := 0
			for _, r := range records {
